import "./card-grid.css";

export interface CardGridItem {
  title: string;
  subtitle: string;
  imageUrl: string;
}

export interface CardGridProps {
  heading: string;
  columns: "2" | "3" | "4";
  items: CardGridItem[];
}

export function CardGridRender({ heading, columns, items }: CardGridProps) {
  return (
    <div className="p1-card-grid p1-block">
      <div className="p1-card-grid__inner">
        {heading && <h2 className="p1-card-grid__heading">{heading}</h2>}
        <div className="p1-card-grid__grid" data-columns={columns}>
          {(items || []).map((item, i) => (
            <div key={i} className="p1-card-grid__card">
              {item.imageUrl && (
                <div className="p1-card-grid__img-wrap">
                  <img src={item.imageUrl} alt="" className="p1-card-grid__img" />
                </div>
              )}
              <div className="p1-card-grid__body">
                <div className="p1-card-grid__title">{item.title}</div>
                <div className="p1-card-grid__subtitle">{item.subtitle}</div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta, wireframe } from '../define-meta';
import { CardGridRender, type CardGridProps, type CardGridItem } from "./card-grid";
export type { CardGridProps, CardGridItem };

export const CardGridBlock: ComponentConfig<CardGridProps> = {
  fields: {
    heading: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "A short section heading of 2–5 words. Plain text, sentence case." },
    },
    columns: {
      type: "select" as const,
      options: [
        { label: "2", value: "2" },
        { label: "3", value: "3" },
        { label: "4", value: "4" },
      ],
    },
    items: {
      type: "array" as const,
      arrayFields: {
        title: { type: "text" as const, contentEditable: true, visible: false },
        subtitle: { type: "text" as const, contentEditable: true, visible: false },
        imageUrl: { type: "text" as const },
      },
      defaultItemProps: {
        title: "Company",
        subtitle: "Industry · Result",
        imageUrl: wireframe(600, 400),
      },
      getItemSummary: (item: CardGridItem) => item.title || "Card",
    },
  },
  defaultProps: {
    heading: "Customer stories",
    columns: "3",
    items: [
      { title: "Northwind", subtitle: "Retail · 38% faster launches", imageUrl: wireframe(600, 400) },
      { title: "Atlas Media", subtitle: "Publishing · 2M monthly reads", imageUrl: wireframe(600, 400) },
      { title: "Brightline", subtitle: "SaaS · 4.9/5 satisfaction", imageUrl: wireframe(600, 400) },
    ],
  },
  render: CardGridRender,
};

export const meta = defineMeta({
  title: 'Card Grid',
  description: 'Responsive 2–4 column grid of image+title+subtitle cards with an optional section heading; use for feature or product showcases.',
  categories: ["showcase"],
  published: true,
});

.p1-card-grid__inner {
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
}

.p1-card-grid__heading {
  font-family: var(--p1-font-heading);
  font-size: var(--p1-text-2xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
  line-height: var(--p1-leading-tight);
  margin-block-end: var(--p1-space-xl);
  text-align: center;
}

.p1-card-grid__grid {
  display: grid;
  gap: var(--p1-space-md);
  grid-template-columns: 1fr;
}

@media (width >= 40rem) {
  .p1-card-grid__grid { grid-template-columns: repeat(2, 1fr); }
}

@media (width >= 64rem) {
  .p1-card-grid__grid[data-columns="2"] { grid-template-columns: repeat(2, 1fr); }
  .p1-card-grid__grid[data-columns="3"] { grid-template-columns: repeat(3, 1fr); }
  .p1-card-grid__grid[data-columns="4"] { grid-template-columns: repeat(4, 1fr); }
}

.p1-card-grid__card {
  background-color: var(--p1-surface-default);
  border: 1px solid var(--p1-border);
  border-radius: var(--p1-radius-card);
  box-shadow: var(--p1-shadow-sm);
  overflow: hidden;
}

.p1-card-grid__img-wrap {
  aspect-ratio: 4 / 3;
  background-color: var(--p1-surface-subtle);
  overflow: hidden;
}

.p1-card-grid__img {
  block-size: 100%;
  inline-size: 100%;
  object-fit: cover;
}

.p1-card-grid__body { padding: var(--p1-space-md); }

.p1-card-grid__title {
  color: var(--p1-fg-default);
  font-size: var(--p1-text-lg);
  font-weight: var(--p1-weight-bold);
  line-height: var(--p1-leading-tight);
}

.p1-card-grid__subtitle {
  color: var(--p1-fg-muted);
  font-size: var(--p1-text-sm);
  margin-block-start: var(--p1-space-xs);
}

